// The stateful core: one pure step function over a single job's record.
// host.impl.ts keeps one record per job id and routes every command through step().

export type Status = 'queued' | 'running' | 'cancelling' | 'succeeded' | 'failed' | 'cancelled' | 'held';

export interface JobRecord {
  status: Status;
  tries: number;
  maxTries: number;
}

export type Command = 'submit' | 'claim' | 'succeed' | 'fail' | 'lost' | 'cancel' | 'hold' | 'release' | 'failPermanently' | 'resubmit';

export type StepResult = { ok: true; next: JobRecord } | { ok: false; reason: string };

export const MIN_TRIES = 1;
export const MAX_TRIES = 3;

function refuse(reason: string): StepResult {
  return { ok: false, reason };
}

function accept(next: JobRecord): StepResult {
  return { ok: true, next };
}

/** Applies a command to a job; `job` is null when no job has that id. */
export function step(job: JobRecord | null, command: Command, maxTries?: number): StepResult {
  if (command === 'submit') {
    if (job !== null) return refuse('job already exists');
    if (typeof maxTries !== 'number' || !Number.isInteger(maxTries) || maxTries < MIN_TRIES || maxTries > MAX_TRIES) {
      return refuse(`maxTries must be an integer from ${MIN_TRIES} to ${MAX_TRIES}`);
    }
    return accept({ status: 'queued', tries: 0, maxTries });
  }
  if (job === null) return refuse('no such job');

  switch (command) {
    case 'claim':
      if (job.status !== 'queued') return refuse(`cannot claim a ${job.status} job`);
      if (job.tries >= job.maxTries) return refuse('no tries left');
      return accept({ ...job, status: 'running', tries: job.tries + 1 });
    case 'succeed':
      if (job.status !== 'running' && job.status !== 'cancelling') return refuse(`cannot succeed a ${job.status} job`);
      return accept({ ...job, status: 'succeeded' });
    case 'fail':
    case 'lost':
      if (job.status === 'cancelling') return accept({ ...job, status: 'cancelled' });
      if (job.status !== 'running') return refuse(`cannot ${command} a ${job.status} job`);
      return accept({ ...job, status: job.tries < job.maxTries ? 'queued' : 'failed' });
    case 'failPermanently':
      if (job.status === 'cancelling') return accept({ ...job, status: 'cancelled' });
      if (job.status !== 'running') return refuse(`cannot fail a ${job.status} job`);
      return accept({ ...job, status: 'failed' });
    case 'cancel':
      if (job.status === 'queued' || job.status === 'held') return accept({ ...job, status: 'cancelled' });
      if (job.status === 'running') return accept({ ...job, status: 'cancelling' });
      return refuse(`cannot cancel a ${job.status} job`);
    case 'hold':
      if (job.status !== 'queued') return refuse(`cannot hold a ${job.status} job`);
      return accept({ ...job, status: 'held' });
    case 'release':
      if (job.status !== 'held') return refuse(`cannot release a ${job.status} job`);
      return accept({ ...job, status: 'queued' });
    default:
      return refuse(`unknown command ${String(command)}`);
  }
}

import type { CreateHost, Host, JobView, Outcome } from '../host.ts';
import { step } from './jobs.ts';
import type { Command, JobRecord } from './jobs.ts';

/** Observes every command, accepted or refused, after it settles. */
export type StepListener = (event: {
  job: string;
  command: Command;
  maxTries?: number;
  pre: JobRecord | null;
  post: JobRecord | null;
  outcome: Outcome;
}) => void;

export function createSystem(listener: StepListener = () => {}): Host {
  const jobs = new Map<string, JobRecord>();

  function run(job: string, command: Command, maxTries?: number): Outcome {
    const pre = jobs.get(job) ?? null;
    const result = step(pre, command, maxTries);
    let outcome: Outcome;
    if (result.ok) {
      jobs.set(job, result.next);
      outcome = { ok: true };
    } else {
      outcome = { ok: false, reason: result.reason };
    }
    const post = jobs.get(job) ?? null;
    listener({ job, command, maxTries, pre: pre && { ...pre }, post: post && { ...post }, outcome });
    return outcome;
  }

  return {
    async submit(job, maxTries) { return run(job, 'submit', maxTries); },
    async claim(job) { return run(job, 'claim'); },
    async succeed(job) { return run(job, 'succeed'); },
    async fail(job) { return run(job, 'fail'); },
    async failPermanently(job) { return run(job, 'failPermanently'); },
    async lost(job) { return run(job, 'lost'); },
    async cancel(job) { return run(job, 'cancel'); },
    async hold(job) { return run(job, 'hold'); },
    async release(job) { return run(job, 'release'); },
    async job(job): Promise<JobView | null> {
      const record = jobs.get(job);
      return record ? { status: record.status, tries: record.tries, maxTries: record.maxTries } : null;
    },
  };
}

const createHost: CreateHost = async () => createSystem();

export default createHost;

