import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('submit validates maxTries and duplicate ids', async () => {
  const h = await createHost();
  for (const bad of [0, 4, -1, 1.5, NaN]) assert.equal((await h.submit('a', bad)).ok, false);
  assert.equal(await h.job('a'), null);
  assert.deepEqual(await h.submit('a', 2), { ok: true });
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 0, maxTries: 2 });
  assert.equal((await h.submit('a', 1)).ok, false);
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 0, maxTries: 2 });
});

test('commands on unknown jobs are refused', async () => {
  const h = await createHost();
  for (const c of ['claim', 'succeed', 'fail', 'lost', 'cancel'] as const) {
    const r = await h[c]('nope');
    assert.equal(r.ok, false);
    assert.equal(typeof (r as { reason: string }).reason, 'string');
  }
  assert.equal(await h.job('nope'), null);
});

test('retries up to the limit, then fails', async () => {
  const h = await createHost();
  await h.submit('a', 2);
  assert.deepEqual(await h.claim('a'), { ok: true });
  assert.deepEqual(await h.job('a'), { status: 'running', tries: 1, maxTries: 2 });
  assert.equal((await h.claim('a')).ok, false);
  await h.fail('a');
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 1, maxTries: 2 });
  await h.claim('a');
  await h.lost('a');
  assert.deepEqual(await h.job('a'), { status: 'failed', tries: 2, maxTries: 2 });
  for (const c of ['claim', 'succeed', 'fail', 'lost', 'cancel'] as const) assert.equal((await h[c]('a')).ok, false);
});

test('succeed only from running or cancelling', async () => {
  const h = await createHost();
  await h.submit('a', 1);
  assert.equal((await h.succeed('a')).ok, false);
  await h.claim('a');
  assert.deepEqual(await h.succeed('a'), { ok: true });
  assert.deepEqual(await h.job('a'), { status: 'succeeded', tries: 1, maxTries: 1 });
});

test('cancel: queued -> cancelled; running -> cancelling -> succeeded/cancelled', async () => {
  const h = await createHost();
  await h.submit('q', 3);
  assert.deepEqual(await h.cancel('q'), { ok: true });
  assert.equal((await h.job('q'))!.status, 'cancelled');
  assert.equal((await h.cancel('q')).ok, false);

  await h.submit('s', 3);
  await h.claim('s');
  await h.cancel('s');
  assert.equal((await h.job('s'))!.status, 'cancelling');
  assert.equal((await h.cancel('s')).ok, false);
  assert.equal((await h.claim('s')).ok, false);
  await h.succeed('s');
  assert.deepEqual(await h.job('s'), { status: 'succeeded', tries: 1, maxTries: 3 });

  for (const c of ['fail', 'lost'] as const) {
    await h.submit(c, 3);
    await h.claim(c);
    await h.cancel(c);
    assert.deepEqual(await h[c](c), { ok: true });
    assert.deepEqual(await h.job(c), { status: 'cancelled', tries: 1, maxTries: 3 });
  }
});

test('hold and release', async () => {
  const h = await createHost();
  assert.equal((await h.hold('x')).ok, false);
  assert.equal((await h.release('x')).ok, false);
  await h.submit('a', 2);
  assert.equal((await h.release('a')).ok, false);
  assert.deepEqual(await h.hold('a'), { ok: true });
  assert.deepEqual(await h.job('a'), { status: 'held', tries: 0, maxTries: 2 });
  assert.equal((await h.hold('a')).ok, false);
  for (const c of ['claim', 'succeed', 'fail', 'lost'] as const) assert.equal((await h[c]('a')).ok, false);
  assert.deepEqual(await h.job('a'), { status: 'held', tries: 0, maxTries: 2 });
  assert.deepEqual(await h.release('a'), { ok: true });
  assert.equal((await h.job('a'))!.status, 'queued');
  await h.claim('a');
  assert.equal((await h.hold('a')).ok, false);
  await h.fail('a');
  assert.deepEqual(await h.hold('a'), { ok: true });
  assert.deepEqual(await h.job('a'), { status: 'held', tries: 1, maxTries: 2 });
  assert.deepEqual(await h.cancel('a'), { ok: true });
  assert.deepEqual(await h.job('a'), { status: 'cancelled', tries: 1, maxTries: 2 });
  assert.equal((await h.release('a')).ok, false);
  assert.equal((await h.hold('a')).ok, false);
});

