// Captures real execution traces from src/host.impl.ts for polygraph replay.
// Explores the implementation breadth-first over the contract's (action, data)
// domain for one job id; for every reachable state and every action it runs the
// shortest path plus that action on a fresh system and writes one NDJSON trace.
// Run: node spec/capture.ts
import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { createSystem } from '../src/host.impl.ts';
import type { JobRecord } from '../src/jobs.ts';

type Step = { action: string; data: { maxTries?: number } };
type State = { status: string; tries: number; maxTries: number };

const JOB = 'j';
const STEPS: Step[] = [
  ...[0, 1, 2, 3, 4].map((maxTries) => ({ action: 'SUBMIT', data: { maxTries } })),
  ...['CLAIM', 'SUCCEED', 'FAIL', 'FAIL_PERMANENTLY', 'LOST', 'CANCEL', 'HOLD', 'RELEASE'].map((action) => ({ action, data: {} })),
];

const project = (r: JobRecord | null): State =>
  r ? { status: r.status, tries: r.tries, maxTries: r.maxTries } : { status: 'none', tries: 0, maxTries: 0 };

async function run(path: Step[]): Promise<{ windows: string[]; end: State }> {
  const windows: string[] = [];
  let current: Step | undefined;
  let end: State = project(null);
  const host = createSystem((e) => {
    end = project(e.post);
    windows.push(JSON.stringify({ pre: project(e.pre), action: current!.action, data: current!.data, post: end }));
  });
  for (const s of path) {
    current = s;
    if (s.action === 'SUBMIT') await host.submit(JOB, s.data.maxTries!);
    else if (s.action === 'FAIL_PERMANENTLY') await host.failPermanently(JOB);
    else await host[s.action.toLowerCase() as 'claim' | 'succeed' | 'fail' | 'lost' | 'cancel' | 'hold' | 'release'](JOB);
  }
  return { windows, end };
}

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });

const seen = new Map<string, Step[]>([[JSON.stringify(project(null)), []]]);
const queue: Step[][] = [[]];
let files = 0;
while (queue.length) {
  const path = queue.shift()!;
  for (const s of STEPS) {
    const { windows, end } = await run([...path, s]);
    writeFileSync(new URL(`t${String(files++).padStart(4, '0')}.ndjson`, dir), windows.join('\n') + '\n');
    const key = JSON.stringify(end);
    if (!seen.has(key)) { seen.set(key, [...path, s]); queue.push([...path, s]); }
  }
}
console.log(`reachable states: ${seen.size}, trace files: ${files}`);

